"""Build a beginner guide from frozen, already verified stock experiment outputs."""
import csv,json,pathlib
import numpy as np
BASE=pathlib.Path(__file__).resolve().parent.parent
if (BASE/'pattern-samsung-20d').exists(): DOCS=BASE
else:DOCS=BASE/'docs'
OUT=DOCS/'pattern-guide';OUT.mkdir(exist_ok=True)
stocks={};pairs=[]
for key,name in [('samsung','삼성전자'),('hynix','SK하이닉스')]:
 root=DOCS/f'pattern-{key}-20d'
 r=json.loads((root/'report_data.json').read_text(encoding='utf-8'));e=r['experiments'][0]
 with (root/'daily_prices.csv').open(encoding='utf-8',newline='') as f:bars=list(csv.DictReader(f))
 assert [a['date'] for a in bars]==r['daily_dates']
 p=np.array(e['predictions']);y=np.array(r['actual_returns']);u=np.array(e['used'])
 stocks[key]={'name':name,'dates':r['daily_dates'],'close':r['daily_closes'],'open':[float(a['open']) for a in bars],'lookback':e['config']['lookback'],'source':r['source'],'summary':{'test_days':len(y),'found_days':sum(n>0 for n in e['counts']),'forecast_days':int(u.sum()),'direction_correct':int((np.sign(p[u])==np.sign(y[u])).sum()),'pattern_up_n':int(((p>0)&u).sum()),'pattern_up_wrong':int(((p>0)&(y<0)&u).sum()),'all_up_wrong':int(((p>0)&(y<0)).sum())}}
 for i,use in enumerate(u):
  if not use:continue
  q=r['test_queries'][i]
  for j,sim in zip(e['neighbors'][i],e['similarities'][i]):
   pairs.append({'stock':key,'q':q,'j':j,'similarity':sim,'prediction':float(p[i]),'count':e['counts'][i]})
def case(key,date,past_date,label):
 a=next(a for a in pairs if a['stock']==key and stocks[key]['dates'][a['q']]==date and stocks[key]['dates'][a['j']]==past_date)
 return {**a,'label':label}
presets=[case('samsung','2026-04-13','2025-09-12','삼성전자 · 닮은 뒤 함께 상승'),case('hynix','2026-03-17','2021-01-26','하이닉스 · 끝에는 함께 상승'),case('hynix','2026-06-17','2024-07-16','하이닉스 · 끝에는 함께 하락')]
wrong=next(a for a in pairs if a['stock']=='hynix' and stocks['hynix']['dates'][a['q']]=='2026-07-09')
presets.append({**wrong,'label':'하이닉스 · 상승 예측이 빗나간 날'})
data={'method':'코사인 유사도 기반 패턴 예측법','snapshot_end':'2026-10-07','stocks':stocks,'presets':presets,'random_pairs':pairs,'case_selection':'Preset examples selected after observing outcomes for explanation. Random examples draw from all retrieved pairs on selected-condition forecast dates, including failures. Neither selects or retrains a model.'}
(OUT/'guide_data.json').write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
html=r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>유사 패턴 예측법 · 최신 안내</title><style>
:root{--ink:#172a3b;--muted:#596a7a;--blue:#1768bf;--orange:#c97013;--line:#dbe3eb;--soft:#f2f6fa}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font:16px/1.7 system-ui,'Malgun Gothic',sans-serif}main{max-width:1150px;margin:auto;padding:32px 22px 60px}h1{font-size:clamp(30px,4vw,45px);line-height:1.3;margin:12px 0 20px;letter-spacing:-1px}h2{font-size:25px;margin:0 0 15px}h3{font-size:18px;margin:12px 0}p{margin:10px 0}.eyebrow{font-size:13px;font-weight:700;color:var(--blue)}.lead{font-size:19px;max-width:870px}section{background:#fff;border:1px solid var(--line);border-radius:16px;padding:26px;margin-top:22px}.muted,small{color:var(--muted)}.steps,.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.step,.card{padding:17px;background:var(--soft);border-radius:10px}.step b{display:block}.controls{display:flex;gap:12px;align-items:end;flex-wrap:wrap}label{display:flex;flex-direction:column;font-size:14px;gap:6px}button,select,input{font:inherit;padding:9px 12px;border:1px solid #b8c8d7;border-radius:8px;max-width:100%;background:#fff}button{color:#195993;background:#eaf3ff;cursor:pointer;font-weight:650}button[aria-pressed=true]{background:var(--blue);color:#fff}:focus-visible{outline:3px solid #7eafe2;outline-offset:3px}.stepbuttons{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.value{font-size:25px;font-weight:750;display:block}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px}svg{width:100%;height:auto;background:#fbfcfe;border:1px solid var(--line);border-radius:9px}svg text{font-family:system-ui;font-size:12px;fill:var(--muted)}.legend{display:flex;gap:18px;font-size:14px;flex-wrap:wrap}.dot{display:inline-block;width:12px;height:12px;border-radius:50%;margin-right:6px}.note{padding:14px 18px;background:#fff5e8;border-left:4px solid #d88a34;border-radius:5px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:9px}table{width:100%;border-collapse:collapse;font-size:14px;font-variant-numeric:tabular-nums}th,td{padding:12px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}th{background:var(--soft)}th:first-child,td:first-child{text-align:left}a{color:var(--blue);text-underline-offset:3px}.links{display:flex;gap:20px;flex-wrap:wrap;margin:15px 0}[hidden]{display:none!important}footer{color:var(--muted);font-size:13px;margin-top:24px}input[type=number]{width:185px}@media(max-width:720px){main{padding:20px 12px 40px}section{padding:20px 15px}.steps,.cards,.grid2{grid-template-columns:1fr}h2{font-size:22px}.stepbuttons button{flex:1;min-width:130px}}
</style></head><body><main><header><div class="eyebrow">최신 안내 · 2026-10-08 · 실제 자료는 2026-10-07까지</div><h1>코사인 유사도 기반<br>패턴 예측법</h1><p class="lead">“지금과 닮은 차트가 과거에 있었어? 있었다면, 그 뒤에는 어떻게 움직였어?”<br>이 질문에 답하는 방법입니다. 짧게 <b>유사 패턴 예측법</b>이라고 부릅니다.</p></header>
<section><h2>세 단계면 이해할 수 있어요</h2><div class="steps"><div class="step"><b>1. 지금 차트를 가져옵니다</b>최근 일정 기간의 종가를 모읍니다. 거래일은 주식시장이 열린 날입니다.</div><div class="step"><b>2. 닮은 과거를 찾습니다</b>가격 수준 대신 모양을 비교합니다. 코사인 유사도는 두 모양이 얼마나 닮았는지 나타내는 점수입니다.</div><div class="step"><b>3. 그 뒤 움직임을 봅니다</b>과거 사례가 끝난 뒤 20거래일 동안 어떻게 움직였는지 참고합니다. 여러 사례의 결과를 합쳐 예측할 수도 있습니다.</div></div><p class="note"><b>유사도 98%는 예측 정확도 98%가 아닙니다.</b> 이전 차트가 닮았다는 뜻입니다. 그 뒤에도 같은 방향으로 움직였는지는 별도로 확인해야 합니다.</p></section>
<section id="walkthrough"><h2>실제 사례를 그래프로 따라가 보기</h2><div class="controls"><label>설명할 사례<select id="case" aria-label="설명할 사례"></select></label><button id="random">무작위 과거 시험 사례</button></div><div class="stepbuttons"><button data-step="1">1 · 최근 차트</button><button data-step="2">2 · 닮은 과거</button><button data-step="3">3 · 그 뒤 결과</button></div><p id="explain" class="note" aria-live="polite"></p><div class="legend"><span><i class="dot" style="background:#1768bf"></i>이번 사례</span><span><i class="dot" style="background:#c97013"></i>닮은 과거 사례</span></div><div class="grid2"><div><h3>이 두 모양이 닮았어요</h3><svg id="input-chart" viewBox="0 0 510 300" role="img" aria-label="이번 차트와 닮은 과거 차트 모양 비교"></svg><p id="input-label" class="muted"></p><small>각 입력 구간의 최저를 0, 최고를 1로 바꿔 비교합니다. 가격 수준과 등락 폭은 지워집니다.</small></div><div><h3>그 뒤에는 각각 이렇게 움직였어요</h3><svg id="future-chart" viewBox="0 0 510 300" role="img" aria-label="이번 사례와 과거 사례 이후 20일 수익률 비교"></svg><p id="future-label" class="muted"></p><small>두 선은 모두 실제 과거 기록입니다. 이번 사례도 결과가 관측된 날짜를 골랐습니다. 모델이 매일 이 경로를 예측했다는 뜻은 아닙니다.</small></div></div><div id="outcome-cards" class="cards" style="margin-top:18px"></div><p id="forecast-note" class="muted"></p><p class="muted">설명용 사례는 결과를 확인한 뒤 골랐습니다. 무작위 버튼은 선택 조건에서 실제 검색된 사례 중 하나를 보여주며, 성공한 것만 고르지 않습니다.</p></section>
<section><h2>얼마를 넣었으면 얼마가 됐을까?</h2><p>위에서 고른 날짜에 매수했다고 가정하는 계산표입니다. <b>기준일 다음 거래일 시가에 매수하고, 결과일 종가에 매도</b>한다고 가정합니다. 과거의 닮은 사례도 같은 방식으로 계산합니다.</p><div class="controls"><label>투자금 (원)<input id="capital" type="number" min="0" max="1000000000000" step="100000" value="10000000" aria-label="투자금 원"></label><label>매수 비용 (%)<input id="buy-fee" type="number" min="0" max="10" step="0.01" value="0" aria-label="매수 비용 퍼센트"></label><label>매도 비용 (%)<input id="sell-fee" type="number" min="0" max="10" step="0.01" value="0" aria-label="매도 비용 퍼센트"></label></div><div id="money" class="tablewrap" style="margin-top:18px"></div><p id="money-detail" class="muted" aria-live="polite"></p><p class="note">실제 주문이나 검증된 매매 전략의 수익이 아니라 <b>가격 기록을 이용한 가정 계산</b>입니다. 비용 기본값은 0이며 실제 증권사 수수료·세율을 반영한 값이 아닙니다. 정수 주만 사고 남은 금액은 현금으로 둡니다. 입력 비용은 원 단위로 반올림합니다. 표시된 시가·종가에 정확히 거래할 수 있다고 가정하며 배당, 중간 매도·손절, 현금 이자는 포함하지 않습니다.</p><small>차트의 “기준일 종가 → 20일 뒤 종가 수익률”과 계산표의 “다음 날 시가 → 결과일 종가 투자 수익률”은 매수 가격이 달라서 수치도 다를 수 있습니다. 하락 예시도 매수했다고 가정해 손실을 보여줍니다.</small></section>
<section><h2>그런 패턴이 실제로 몇 번 있었나요?</h2><p>2026년 중 다음 20거래일 결과까지 확인할 수 있는 <b>166개 기준일</b>을 각각 조사했습니다. 그중 닮은 과거 후보가 하나라도 있었던 날짜와, 사례 3개 이상으로 예측한 날짜를 구분합니다.</p><div id="counts" class="tablewrap"></div><p class="muted">삼성전자는 검증에서 선택된 100거래일·98% 초과, 하이닉스는 60거래일·98% 초과 기준입니다. 같은 48조건을 2022~2025년으로 비교해 선택했고 2026년은 선택에 쓰지 않았습니다. 후보 1~2개도 “과거에 있었다”는 검색 답에는 포함됩니다.</p><p class="note">166개 날짜의 이후 기간은 서로 겹칩니다. 서로 다른 166번의 독립 사건이 아닙니다. 또 같은 과거 사례가 여러 날짜에 검색될 수 있습니다. 그래서 “닮은 사례가 많았다”를 독립적인 성공 증거 수로 읽으면 안 됩니다.</p><details><summary>48가지 조건이란?</summary><p>입력 길이 10·20·60·100거래일의 4가지, 사례 선택 방법 6가지(유사도 90·95·98% 초과 또는 상위 3·5·10개), 결과 집계 평균·중앙값의 2가지입니다. 4 × 6 × 2 = 48입니다. 모두 결과 기간은 다음 20거래일로 고정했습니다.</p></details></section>
<section><h2>검색과 예측, 매매를 구분해서 보기</h2><p><b>검색:</b> 닮은 과거가 있었는지 답하고 그 뒤 기록을 보여줍니다. 없으면 이 기준에서는 없다고 답하면 됩니다.</p><p><b>예측:</b> 검색한 여러 사례의 이후 수익률을 합칩니다. 닮았다고 해서 미래까지 같아지는 것은 아닙니다.</p><p class="note">적중률만 보면 오해할 수 있습니다. 삼성전자의 패턴 예측 10일은 모두 실제 상승이어서 항상 상승을 말해도 10번 모두 맞습니다. 하이닉스의 패턴 예측 44일은 실제 하락이 29일이라 모두 하락을 가정해도 약 66%가 맞습니다. 이는 사후 결과 분포를 설명하는 비교이며 미래의 매매 규칙으로 검증한 것은 아닙니다.</p><p><b>매매:</b> 얼마를 살지, 언제 팔지, 중간에 예상과 달라지면 어떻게 나올지까지 정해야 합니다. 현재 계산표에는 중간 대응 규칙을 넣지 않았습니다.</p><div class="links"><a href="../pattern-samsung-20d/">삼성전자 전체 보고서</a><a href="../pattern-hynix-20d/">하이닉스 전체 보고서 · 빗나간 날짜</a><a href="guide_data.json" download>안내 페이지 원자료 JSON</a><a href="https://github.com/jhs512/samsung-stock-prediction-lab">GitHub 코드·자료</a><a href="../">기존 교육 실험실</a></div><p class="muted">원본 방법: <a href="https://github.com/teddylee777/stock-pattern">테디노트 stock-pattern</a>. 이번 실험은 미래 자료 검색을 차단하고 중복 사례를 제외했으며, 결과 기간을 20거래일로 바꾼 비교입니다. 가격 제공처 간 차이와 배당·가격 조정 한계는 전체 보고서에 기록했습니다.</p></section><footer>실제 API 가격 스냅샷으로 만든 설명입니다. 예시 선택과 계산 가정이 공개되어 있고, 결과 CSV와 실행 코드는 각 보고서에서 내려받을 수 있습니다.</footer></main>
<script id="guide-data" type="application/json">__DATA__</script><script>
'use strict';const D=JSON.parse(document.getElementById('guide-data').textContent),$=id=>document.getElementById(id),won=v=>Math.round(v).toLocaleString('ko-KR')+'원',pct=v=>(v*100).toFixed(2)+'%',signed=v=>(v>=0?'+':'')+pct(v);let active=D.presets[0],step=1;
function norm(a){const lo=Math.min(...a),hi=Math.max(...a);return a.map(v=>hi>lo?(v-lo)/(hi-lo):0)}
function chart(id,lines,normalized=false){const el=$(id),W=510,H=300,L=54,R=20,T=24,B=39,w=W-L-R,h=H-T-B;if(!lines.length){el.innerHTML='<text x="255" y="150" text-anchor="middle">「3 · 그 뒤 결과」를 눌러 확인하세요</text>';return}let vals=lines.flatMap(a=>a.values),lo=normalized?0:Math.min(0,...vals),hi=normalized?1:Math.max(0,...vals);if(hi-lo<1e-9){hi+=.01;lo-=.01}if(!normalized){const pad=(hi-lo)*.12;lo-=pad;hi+=pad}const n=lines[0].values.length,X=i=>L+i*w/(n-1),Y=v=>T+(hi-v)*h/(hi-lo);let out='';for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;out+=`<line x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" stroke="#e0e8ee"/><text x="${L-8}" y="${Y(v)+4}" text-anchor="end">${normalized?v.toFixed(2):(v*100).toFixed(0)+'%'}</text>`}if(!normalized)out+=`<line x1="${L}" x2="${W-R}" y1="${Y(0)}" y2="${Y(0)}" stroke="#8293a5" stroke-dasharray="4 4"/>`;for(const a of lines)out+=`<polyline fill="none" stroke="${a.color}" stroke-width="2.7" points="${a.values.map((v,i)=>X(i)+','+Y(v)).join(' ')}"/>`;out+=`<text x="${L}" y="${H-12}">${normalized?'입력 구간 시작':'기준일'}</text><text x="${W-R}" y="${H-12}" text-anchor="end">${normalized?'기준일':'20거래일 뒤'}</text>`;el.innerHTML=out}
function render(){const a=active,s=D.stocks[a.stock],q=a.q,j=a.j,w=s.lookback,actual=s.close[q+20]/s.close[q]-1,past=s.close[j+20]/s.close[j]-1;document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.step)===step)));$('explain').innerHTML=step===1?`<b>1. ${s.name} · ${s.dates[q]}의 차트를 봅니다.</b><br>그날까지 최근 ${w}거래일, 즉 시장이 열린 날 ${w}일치 종가를 가져왔습니다.`:step===2?`<b>2. 닮은 과거가 있었습니다.</b><br>${s.dates[j]}까지의 과거 ${w}거래일 구간이 유사도 ${(a.similarity*100).toFixed(2)}%로 잡혔습니다. 두 선의 오르내리는 모양을 비교해 보세요.`:`<b>3. 그 뒤 20거래일을 비교합니다.</b><br>과거는 ${signed(past)}, 이번 실제 결과는 ${signed(actual)}였습니다. ${Math.sign(past)===Math.sign(actual)?'끝에 움직인 방향은 같았습니다. 중간 경로까지 같은지는 그래프로 확인하세요.':'이번에는 끝에 움직인 방향부터 달랐습니다.'}`;
const lines=[{values:norm(s.close.slice(q-w+1,q+1)),color:'#1768bf'}];if(step>=2)lines.push({values:norm(s.close.slice(j-w+1,j+1)),color:'#c97013'});chart('input-chart',lines,true);chart('future-chart',step===3?[{values:s.close.slice(q,q+21).map(v=>v/s.close[q]-1),color:'#1768bf'},{values:s.close.slice(j,j+21).map(v=>v/s.close[j]-1),color:'#c97013'}]:[]);$('input-label').textContent='이번: '+s.dates[q-w+1]+'~'+s.dates[q]+(step>=2?' / 과거: '+s.dates[j-w+1]+'~'+s.dates[j]:'');$('future-label').textContent=step===3?'이번 결과일 '+s.dates[q+20]+' / 과거 결과일 '+s.dates[j+20]:'';$('outcome-cards').hidden=step<3;$('outcome-cards').innerHTML=[['닮은 과거의 이후',signed(past)],['이번에 실제 일어난 일',signed(actual)],['당시 여러 사례를 합친 예측',signed(a.prediction)]].map(([x,y])=>`<div class="card"><small>${x}</small><span class="value">${y}</span></div>`).join('');$('forecast-note').textContent=step===3?`그래프에서는 과거 사례 하나를 비교했습니다. 당시 예측은 검색된 ${a.count}개 사례를 합친 ${signed(a.prediction)}였고, 이 과거 사례 하나의 결과를 미리 정답으로 고른 것은 아닙니다.`:'';money()}
function number(id,lo,hi){const v=Number($(id).value);return Math.min(hi,Math.max(lo,Number.isFinite(v)?v:0))}
function money(){const a=active,s=D.stocks[a.stock],capital=Math.floor(number('capital',0,1e12)),buy=number('buy-fee',0,10)/100,sell=number('sell-fee',0,10)/100;const rows=[];for(const [label,k] of [['이번 사례',a.q],['닮은 과거',a.j]]){const entry=s.open[k+1],exit=s.close[k+20];let shares=Math.floor(capital/(entry*(1+buy))),cost=Math.round(shares*entry*buy),cash=capital-shares*entry-cost;if(cash<0&&shares>0){shares--;cost=Math.round(shares*entry*buy);cash=capital-shares*entry-cost;}const sellCost=Math.round(shares*exit*sell),final=cash+shares*exit-sellCost,profit=final-capital;rows.push(`<tr><td>${label}</td><td>${s.dates[k+1]}<br>${won(entry)}</td><td>${s.dates[k+20]}<br>${won(exit)}</td><td>${shares.toLocaleString('ko-KR')}주</td><td>${won(cash)}</td><td>${won(cost+sellCost)}</td><td>${won(final)}</td><td>${profit>=0?'+':''}${won(profit)}<br>${capital?signed(profit/capital):'—'}</td></tr>`)}$('money').innerHTML='<table><thead><tr><th>대상</th><th>매수일 / 시가</th><th>매도일 / 종가</th><th>매수 수량</th><th>남은 현금</th><th>총 비용</th><th>최종 금액</th><th>이익 / 손실</th></tr></thead><tbody>'+rows.join('')+'</tbody></table>';$('money-detail').textContent=`${s.name}에 ${won(capital)}을 넣었다고 가정한 계산입니다. 1주 가격과 비용보다 투자금이 적으면 0주이며 금액은 현금으로 남습니다.`}
$('case').innerHTML=D.presets.map((a,i)=>`<option value="${i}">${a.label}</option>`).join('');$('case').addEventListener('change',()=>{if($('case').value==='random'){$('random').click();return;}active=D.presets[Number($('case').value)];step=1;render()});$('random').addEventListener('click',()=>{active=D.random_pairs[Math.floor(Math.random()*D.random_pairs.length)];let custom=$('case').querySelector('option[value=random]');if(!custom){custom=document.createElement('option');custom.value='random';$('case').append(custom)}custom.textContent=D.stocks[active.stock].name+' · 무작위 사례';$('case').value='random';step=1;render()});document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{step=Number(b.dataset.step);render()}));for(const id of ['capital','buy-fee','sell-fee'])$(id).addEventListener('input',money);
const countRows=Object.values(D.stocks).map(s=>{const a=s.summary;return `<tr><td>${s.name}</td><td>${a.test_days}일</td><td>${a.found_days}일</td><td>${a.test_days-a.found_days}일</td><td>${a.forecast_days}일</td><td>${a.direction_correct}/${a.forecast_days} (${(a.direction_correct/a.forecast_days*100).toFixed(1)}%)</td><td>${a.pattern_up_wrong}/${a.pattern_up_n}</td></tr>`});$('counts').innerHTML='<table><thead><tr><th>종목</th><th>조사한 기준일</th><th>과거 후보 있음</th><th>후보 없음</th><th>3개 이상으로 예측</th><th>그 예측의 방향 적중</th><th>상승 예측→하락</th></tr></thead><tbody>'+countRows.join('')+'</tbody></table>';render();
</script></body></html>'''.replace('__DATA__',payload)
(OUT/'index.html').write_text(html,encoding='utf-8')
print('Built',OUT/'index.html')
